// One progress figure for the whole load, weighted by what each step really downloads
// (compressed sizes): styles, project data, the 3D code, the room model, then scene setup.
const loadSteps=[['css',.005],['data',.035],['code',.09],['room',.62],['setup',.25]];
window.__load=(()=>{const done={};let finished=null,shown=0,stepStart=performance.now(),current='css';
 const actual=()=>loadSteps.reduce((sum,[k,w])=>sum+w*(done[k]||0),0);
 return{
  set(step,f){done[step]=Math.max(done[step]||0,Math.min(1,f));const next=loadSteps.find(([k])=>(done[k]||0)<1);if(next&&next[0]!==current){current=next[0];stepStart=performance.now();}},
  // Steps without byte counts (everything but the room model) creep toward (never past) 85% of their share so the drawing keeps moving.
  target(now){let t=actual();const step=loadSteps.find(([k])=>k===current);if(step&&!finished&&current!=='room'){const f=done[current]||0,creep=(1-Math.exp(-(now-stepStart)/(current==='setup'?2500:1800)))*.85;t+=step[1]*Math.max(0,creep-f);}return finished?1:Math.min(.995,t);},
  get shown(){return shown;},set shown(v){shown=v;},
  finish(){if(finished)return finished;finished=new Promise(r=>{this._resolve=r;});return finished;},
  _resolve:null
 };})();

// Blueprint: edges traced from the room model, packed into BLUEPRINT by scripts/pack-blueprint.py,
// drawn back to front and projected with the same camera the room view uses.
const BLUEPRINT='';
(()=>{const loading=document.getElementById('loading'),canvas=document.getElementById('bp-canvas'),quip=document.getElementById('load-quip'),pct=document.getElementById('load-pct');if(!loading||!canvas)return;
 const ctx=canvas.getContext('2d'),calm=matchMedia('(prefers-reduced-motion: reduce)').matches;
 // Captions rotate every couple of seconds; the first is fixed, the rest shuffle without repeats.
 const lines=['Shhh. Kali is asleep under the desk…','“ajsdofhasuidgnsdlkgnasld” — a message from Mango','Kali is twitching under the desk. Big dream.','Mango is sitting on the keyboard again…','Kali’s paws are running. Winning, probably.','“jjjjjjjjjjjjjjjjjjjjjjjj” — Mango, again','Kali’s tail just thumped twice. Very good dream.','Moving Mango off the warm laptop…','Mango knocked a screw off the bench. Finding it…','Kali heard the treat bag. False alarm.','Mango would like to know if you brought snacks','“;;;;;;;;;;;;;;;;l” — Mango has notes','Kali is snoring. It’s fine. It’s cute.','Mango is supervising. Closely.','Sweeping up the sawdust…','Warming up the soldering iron…','Counting resistors (again)…'];
 const deck=[];let lastSwap=0;const nextLine=()=>{if(!deck.length)deck.push(...lines.slice(1).sort(()=>Math.random()-.5));return deck.pop();};
 let polys=null,monitorEnd=.08,screen=[],total=0,cache=null,cacheCtx=null,cachedUpTo=0,cachedLen=0,W=0,H=0,dpr=1;
 // Decode the built-in blueprint (scripts/pack-blueprint.py): per stroke a point count, then
 // zigzag varints in 2 cm units, first point absolute and the rest as deltas.
 try{const bytes=Uint8Array.from(atob(BLUEPRINT),c=>c.charCodeAt(0));let k=0;const next=()=>{let n=0,shift=0,b;do{b=bytes[k++];n+=(b&127)*2**shift;shift+=7;}while(b&128);return n%2?-(n+1)/2:n/2;};
  polys=[];while(k<bytes.length){const count=next(),o=new Float32Array(count*3);let x=0,y=0,z=0;for(let i=0;i<count;i++){x+=next();y+=next();z+=next();o[i*3]=x/50;o[i*3+1]=y/50;o[i*3+2]=z/50;}
   o.monitor=true;for(let i=0;i<o.length;i+=3)if(Math.abs(o[i])>1.25||o[i+1]<1.3||o[i+1]>2.75||o[i+2]<-1.8||o[i+2]>-1.3){o.monitor=false;break;}polys.push(o);}}catch(e){polys=null;}
 // Mirrors cockpit.js: destination('room') + frameStation() for the current viewport.
 function cameraFor(w,h){const aspect=w/h,mobile=w<=900,t=[0,1.45,-1.2],p0=[0,2.68,5.1];const phone=mobile&&h>w;const k=mobile?1.3:Math.max(1,1.65/aspect);const p=phone?[0,2.35,3.6]:p0.map((v,i)=>t[i]+(v-t[i])*k);if(phone)t[1]=1.55;p[0]=Math.min(3.3,Math.max(-3.25,p[0]));p[2]=Math.min(p[2],7.6);p[1]=Math.min(p[1],3.6);
  const widen=aspect<1.25?Math.min(2.4,1.25/aspect):Math.min(1,1.8/aspect);const fov=phone?72:Math.min(84,2*Math.atan(Math.tan(43.8*Math.PI/360)*widen)*180/Math.PI);const offY=0;
  const zx=p[0]-t[0],zy=p[1]-t[1],zz=p[2]-t[2],zl=Math.hypot(zx,zy,zz),z=[zx/zl,zy/zl,zz/zl];let x=[z[2],0,-z[0]];const xl=Math.hypot(...x);x=x.map(v=>v/xl);const y=[z[1]*x[2]-z[2]*x[1],z[2]*x[0]-z[0]*x[2],z[0]*x[1]-z[1]*x[0]];
  return{p,x,y,z,f:1/Math.tan(fov*Math.PI/360),aspect,offY};}
 function project(c,x,y,z){const dx=x-c.p[0],dy=y-c.p[1],dz=z-c.p[2];const zc=-(dx*c.z[0]+dy*c.z[1]+dz*c.z[2]);return [((dx*c.x[0]+dy*c.x[1]+dz*c.x[2])/zc*c.f/c.aspect+1)/2*W,(1-(dx*c.y[0]+dy*c.y[1]+dz*c.y[2])/zc*c.f)/2*H-c.offY];}
 // The main monitor's screen (cockpit.js screenPosition): the welcome and status sit on it.
 function placeCopy(c){const copy=loading.querySelector('.loader-copy');if(!copy)return null;const a=project(c,-1.075,2.63,-1.548),b=project(c,1.075,1.41,-1.548);const r={x:a[0],y:a[1],w:b[0]-a[0],h:b[1]-a[1]};
  copy.style.setProperty('--sx',r.x+'px');copy.style.setProperty('--sy',r.y+'px');copy.style.setProperty('--sw',r.w+'px');copy.style.setProperty('--sh',r.h+'px');copy.style.setProperty('--fs',Math.max(7,Math.min(17,r.w/27))+'px');return r;}
 function layout(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;const c=cameraFor(W,H);const r=placeCopy(c);if(!polys)return;screen=[];total=0;
  // The monitor is drawn first: its screen outline, then every stroke that belongs to the monitors.
  if(r){const box=[r.x,r.y,r.x+r.w,r.y,r.x+r.w,r.y+r.h,r.x,r.y+r.h,r.x,r.y];screen.push({pts:box,len:2*(r.w+r.h),start:0});total=2*(r.w+r.h);}
  const first=[],rest=[];for(const pl of polys){const pts=[];let len=0,prev=null,ok=true;for(let i=0;i<pl.length;i+=3){const dx=pl[i]-c.p[0],dy=pl[i+1]-c.p[1],dz=pl[i+2]-c.p[2];const zc=-(dx*c.z[0]+dy*c.z[1]+dz*c.z[2]);if(zc<.05){ok=false;break;}const sx=((dx*c.x[0]+dy*c.x[1]+dz*c.x[2])/zc*c.f/c.aspect+1)/2*W,sy=(1-(dx*c.y[0]+dy*c.y[1]+dz*c.y[2])/zc*c.f)/2*H-c.offY;if(prev)len+=Math.hypot(sx-prev[0],sy-prev[1]);prev=[sx,sy];pts.push(sx,sy);}
   if(ok&&pts.length>=4)(pl.monitor?first:rest).push({pts,len});}
  for(const s of [...first,...rest]){s.start=total;screen.push(s);total+=s.len;}monitorEnd=(first.reduce((a,s)=>a+s.len,0)+(r?2*(r.w+r.h):0))/Math.max(1,total);
  cache=document.createElement('canvas');cache.width=canvas.width;cache.height=canvas.height;cacheCtx=cache.getContext('2d');cacheCtx.scale(dpr,dpr);style(cacheCtx);cachedUpTo=0;cachedLen=0;}
 function style(g){g.strokeStyle='#e9d6a8';g.globalAlpha=.62;g.lineWidth=.9;g.lineCap='round';g.lineJoin='round';}
 function stroke(g,s,upto){const P=s.pts;g.beginPath();g.moveTo(P[0],P[1]);let run=0,tip=[P[0],P[1]];for(let i=2;i<P.length;i+=2){const seg=Math.hypot(P[i]-P[i-2],P[i+1]-P[i-1]);if(run+seg>=upto){const k=seg?(upto-run)/seg:1;tip=[P[i-2]+(P[i]-P[i-2])*k,P[i-1]+(P[i+1]-P[i-1])*k];g.lineTo(...tip);g.stroke();return tip;}run+=seg;g.lineTo(P[i],P[i+1]);tip=[P[i],P[i+1]];}g.stroke();return tip;}
 function draw(p){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);
  // faint drafting grid
  ctx.globalAlpha=1;ctx.strokeStyle='#e9d6a80d';ctx.lineWidth=1;ctx.beginPath();for(let x=(W%48)/2;x<W;x+=48){ctx.moveTo(x,0);ctx.lineTo(x,H);}for(let y=(H%48)/2;y<H;y+=48){ctx.moveTo(0,y);ctx.lineTo(W,y);}ctx.stroke();
  if(!screen.length)return;const goal=p*total;
  while(cachedUpTo<screen.length&&screen[cachedUpTo].start+screen[cachedUpTo].len<=goal){stroke(cacheCtx,screen[cachedUpTo],Infinity);cachedUpTo++;}
  ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(cache,0,0);ctx.setTransform(dpr,0,0,dpr,0,0);
  // the stroke being drawn right now, with a warm pen tip
  const s=screen[cachedUpTo];if(s&&p<1){style(ctx);const tip=stroke(ctx,s,goal-s.start);ctx.globalAlpha=1;ctx.fillStyle='#f0b850';ctx.shadowColor='#f0b850';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(tip[0],tip[1],2.6,0,7);ctx.fill();ctx.shadowBlur=0;}}
 function caption(p){loading.querySelector('.loader-copy')?.classList.toggle('on',p>=Math.min(.12,monitorEnd*.6)||!polys);pct&&(pct.textContent=Math.floor(p*100));const now=performance.now();if(!lastSwap)lastSwap=now;if(quip&&!calm&&now-lastSwap>2400&&p<.99){lastSwap=now;quip.classList.add('fading');setTimeout(()=>{quip.textContent=nextLine();quip.classList.remove('fading');},300);}}
 addEventListener('resize',layout);layout();
 let finishing=false;const pace={last:0,start:0,speed:0,prevF:0,recent:0};
 window.__loadDone=()=>{if(finishing)return;finishing=true;window.__load.finish();
  // Let the percentage and drawing finish, then fade; tell the room once the loader is gone.
  const t0=performance.now();const wait=()=>{if(window.__load.shown>=.999||performance.now()-t0>900){loading.classList.add('done');setTimeout(()=>{loading.hidden=true;loading.classList.remove('done');window.__load._resolve?.();},calm?0:950);}else requestAnimationFrame(wait);};wait();};
 let lastDrawn=-1;
 function tick(now){requestAnimationFrame(tick);if(loading.hidden||!document.body.classList.contains('workshop-started'))return;
  const L=window.__load,f=L.target(now),dt=Math.min(.1,(now-(pace.last||now))/1000);pace.last=now;pace.start||=now;let v=L.shown;
  if(dt>0)pace.recent+=((f-pace.prevF)/dt-pace.recent)*Math.min(1,dt/2);pace.prevF=f;
  if(calm)v=f;else if(finishing)v=v+(1-v)*Math.min(1,dt*9);else{
   // Real speed (overall average, or the recent speed once the model streams) gives a time-left estimate; the shown figure glides
   // toward 100% at the pace that lands there when the download does, never far ahead of reality.
   const elapsed=Math.max(.25,(now-pace.start)/1000),rate=Math.max(f/elapsed,pace.recent*.85),left=rate>0?(1-f)/rate:30,want=(1-v)/Math.max(.3,left);
   pace.speed+=(want-pace.speed)*Math.min(1,dt*3);v=Math.min(v+Math.max(0,pace.speed)*dt,f+.02,.99);}
  if(finishing&&1-v<.003)v=1;L.shown=Math.max(L.shown,v);if(L.shown!==lastDrawn){lastDrawn=L.shown;draw(L.shown);}caption(L.shown);}
 requestAnimationFrame(tick);
})();

// No static 3D imports. The main route opens the room; data-saving visitors get a choice first.
const entry=document.getElementById('entry'),button=document.getElementById('enter-workshop');
let starting=false;
async function startWorkshop(){
 if(starting)return;starting=true;button.disabled=true;
 document.body.classList.add('workshop-started');entry.hidden=true;
 try{
  const css=document.createElement('link');css.rel='stylesheet';css.href='cockpit.css?v=32';document.head.append(css);
  await new Promise((resolve,reject)=>{css.onload=resolve;css.onerror=reject;});window.__load?.set('css',1);
  {const list=['projects.js','portfolio-stories.js?v=8','deep-case-data.js?v=20'];let done=0;for(const src of list){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.append(s);});window.__load?.set('data',++done/list.length);}}
  await import('./cockpit.bundle.js?v=30');window.__load?.set('code',1);
 }catch(error){document.documentElement.classList.remove('autostart');document.body.classList.remove('workshop-started');entry.hidden=false;document.getElementById('entry-note').textContent='The workshop couldn’t load. You can still browse every project in the lightweight site.';starting=false;button.disabled=false;console.warn('Workshop unavailable',error);}
}
button.addEventListener('click',startWorkshop);
const connection=navigator.connection;
if(connection?.saveData||['slow-2g','2g'].includes(connection?.effectiveType))document.getElementById('entry-note').textContent='On a slow connection? Browse projects to keep downloads small. Photos are optional.';
const explicit3D=new URLSearchParams(location.search).get('mode')==='3d';
// ?loader-preview plays the loading screen on a simulated 12-second download on a loop, without loading the room.
const loaderPreview=new URLSearchParams(location.search).has('loader-preview');
if(loaderPreview){document.body.classList.add('workshop-started');entry.hidden=true;const t0=performance.now();const steps=[['css',.02],['data',.06],['code',.18],['room',.9],['setup',1]];let last=0;const run=()=>{const k=(performance.now()-t0)/12000;for(const [step,end] of steps){const start=last;last=end;window.__load.set(step,Math.max(0,Math.min(1,(k-start)/(end-start))));}last=0;if(k<1)requestAnimationFrame(run);else setTimeout(()=>location.reload(),2500);};run();}
const saveData=connection?.saveData||['slow-2g','2g'].includes(connection?.effectiveType);
if(!loaderPreview&&(explicit3D||(document.body.dataset.defaultView==='workshop'&&!saveData)))startWorkshop();

